head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > editModeEventIcon]<br/>viewType='icon' 인 Body Cell 을 편집 모드로 변경하기 위한 마우스 이벤트 종류를 설정합니다.",
    "validation" : [
        "onclick 설정 시, Body Cell 을 클릭하면 편집 모드로 변경됩니다.",
        "미설정 시, Body Cell 을 클릭하면 편집 모드로 변경됩니다.",
        "ondblclick 설정 시, Body Cell 을 더블 클릭하면 편집 모드로 변경됩니다.",
        "editModeEventIcon 속성은 'onsecondclick' 값을 지원하지 않습니다.",
        "inputType 이 'select','autoComplete','checkcombobox','calendar','spinner' 인 Body Cell 에만 적용되며 나머지 경우엔 editModeEvent 속성이 적용됩니다.",
        "Body Cell 이 inputType 이 'checkbox','radio' 이면 편집 모드로 변경되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 조건 셀렉트박스 기본값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    //  con_editModeEventIcon 은 자체 값 select 이므로 값(onclick/ondblclick)을 직접 setValue.
    //  editModeEventIcon default 는 "onclick".
    //  comp_init 이 con 값을 읽어 grid editModeEventIcon 을 결정하므로 반드시 comp_init 전에 기본값을 설정한다.
    con_editModeEventIcon.setValue("onclick");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  editModeEventIcon 은 렌더 시 결정되는 속성이므로 con 변경 후 "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 선택값 (자체 값 select -> getValue)
    let editModeEventIcon = con_editModeEventIcon.getValue();

    $c.gcm.createLabel('label="[전제] GridView editModeEventIcon = con 선택값(현재 " + editModeEventIcon + "). viewType=icon 아이콘 셀 5종: col1=select / col2=calendar / col5=autoComplete / col6=checkcombobox / col7=spinner. 이 중 col2 만 컬럼 editModeEventIcon=onclick 보유(컬럼값 우선), 나머지(col1/col5/col6/col7)는 컬럼 미설정 -> GridView editModeEventIcon 값 적용. col3=checkbox(편집모드 미변경), col4=text. Row 3개.\n[절차] con_editModeEventIcon 선택 -> Target 재생성 -> 아이콘 셀을 설정값에 맞는 마우스 조작으로 편집 진입: onclick=단일클릭 / ondblclick=더블클릭.\n[확인] 아이콘 셀이 편집모드로 진입하는 순간 하단 결과창에 rowIndex/colIndex/columnID/적용 editModeEventIcon 가 자동 출력. 5종 아이콘 셀 모두 editModeEventIcon 을 따르는지 확인. col2 셀은 항상 단일클릭(onclick) 진입, col3(checkbox) 은 편집모드 미진입.\n[미지원] con=onsecondclick 선택 시 editModeEventIcon 은 onsecondclick 미지원 -> 엔진이 onclick 으로 폴백(단일클릭 즉시 편집 진입, 결과창에 [미지원 -> onclick 적용] 표시)."', '', 'label1');

    // 컬럼별 자체 editModeEventIcon (미설정이면 GridView 값 상속) -> onbeforeedit 출력에서 상속/우선 판정에 사용
    //  gridEvt : GridView 에 적용된 editModeEventIcon (con 선택값)
    scwin.gVar = { "colEvt" : { "col2" : "onclick" }, "gridEvt" : editModeEventIcon };

    let strNameSpace = $c.gcm.getNameSpace();

    // select 컬럼 itemset 용 코드/라벨 DataList
    let strGrade = '';
    strGrade += '<w2:dataList ' + strNameSpace + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // 본문 데이터리스트 (아이콘 편집형 컬럼)
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="date"></w2:column>';
    strDl += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDl += '<w2:column id="col6" name="col6" dataType="text"></w2:column>';
    strDl += '<w2:column id="col7" name="col7" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true"></w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);
    dlt_bind.setJSON([
        { "col1": "A", "col2": "20250115", "col5": "A", "col6": "A B", "col7": "5", "col3": "1", "col4": "메모A" },
        { "col1": "B", "col2": "20250220", "col5": "B", "col6": "B C", "col7": "10", "col3": "0", "col4": "메모B" },
        { "col1": "C", "col2": "20250312", "col5": "C", "col6": "A C", "col7": "15", "col3": "1", "col4": "메모C" }
    ], false);

    // target 생성
    //  GridView editModeEventIcon 를 con 선택값으로 설정.
    //  viewType="icon" 인 select/autoComplete/checkcombobox/calendar/spinner 5개 타입 아이콘 셀을 모두 배치하여
    //  editModeEventIcon 이 5개 타입 전부에 적용됨을 검증한다.
    //  col1 : select        + viewType="icon", 컬럼 editModeEventIcon 미설정 -> GridView editModeEventIcon 값 적용
    //  col2 : calendar      + viewType="icon", 컬럼 editModeEventIcon="onclick" 보유 -> 컬럼값 우선
    //         (viewTypeIconImage 는 미설정=false 이므로 editModeEventIcon 이 적용됨)
    //  col5 : autoComplete  + viewType="icon", 컬럼 editModeEventIcon 미설정 -> GridView editModeEventIcon 값 적용
    //  col6 : checkcombobox + viewType="icon", 컬럼 editModeEventIcon 미설정 -> GridView editModeEventIcon 값 적용
    //  col7 : spinner       + viewType="icon", 컬럼 editModeEventIcon 미설정 -> GridView editModeEventIcon 값 적용
    //  col3 : inputType="checkbox" -> 편집모드로 변경되지 않음
    //  col4 : text
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" editModeEventIcon="' + editModeEventIcon + '" ev:onbeforeedit="scwin.target1_onbeforeedit" id="" style="width:900px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1 select/icon (미설정)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="hcol2" value="col2 calendar/icon (=onclick)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="hcol5" value="col5 autoComplete/icon (미설정)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="hcol6" value="col6 checkcombobox/icon (미설정)"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="hcol7" value="col7 spinner/icon (미설정)"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="hcol3" value="col3 (checkbox)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="select" viewType="icon" dataType="text" id="col1" dataList="col1">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="130" inputType="calendar" viewType="icon" dataType="date" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" editModeEventIcon="onclick" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="130" inputType="autoComplete" viewType="icon" dataType="text" id="col5" dataList="col5">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="140" inputType="checkcombobox" viewType="icon" dataType="text" id="col6" dataList="col6">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="90" inputType="spinner" viewType="icon" dataType="text" id="col7" dataList="col7"></w2:column>';
    strTarget += '<w2:column width="90" inputType="checkbox" dataType="text" trueValue="1" falseValue="0" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// viewType="icon" Body Cell 이 실제로 편집 모드로 진입하는 순간(onbeforeedit) 검증값 자동 출력.
//  사용자가 con_editModeEventIcon 설정값에 맞는 마우스 조작(onclick=단일클릭 / ondblclick=더블클릭)으로
//  아이콘 셀을 편집모드에 진입시키면, 그 시점에 편집 셀의 rowIndex/colIndex/columnID 와
//  실제 적용된 editModeEventIcon(상속/우선/미지원폴백 판정)를 출력한다.
//  '적용 editModeEventIcon' 은 엔진이 셀 td 에 설정한 실제값(data-editModeEvent)을 읽어 보고한다.
//  엔진(cellInfo.js)은 아이콘 셀의 editModeEventIcon 을 {onclick, ondblclick} 로만 허용하며,
//  그 외 값(onsecondclick 등)은 onclick 으로 강제한다 -> onsecondclick 미지원(@spec) 을 이 폴백으로 입증한다.
//  -> @spec 규칙(편집모드 진입은 사용자 조작으로 검증, 강제 편집 버튼 금지)을 지키면서 editModeEventIcon 동작을 실제 편집 진입으로 입증한다.
scwin.target1_onbeforeedit = function (rowIndex, columnIndex, value) {
    let colId = '';
    try { colId = scwin.target1.getColumnID(columnIndex); } catch (ex) { colId = ''; }

    let gridEvt = (scwin.gVar && scwin.gVar.gridEvt) ? scwin.gVar.gridEvt : '';                                   // con 선택값 (GridView 요청 editModeEventIcon)
    let colOwn = (scwin.gVar && scwin.gVar.colEvt && scwin.gVar.colEvt[colId]) ? scwin.gVar.colEvt[colId] : '';   // 컬럼 자체 editModeEventIcon
    let requested = colOwn || gridEvt;                                                                            // 요청값: 컬럼값 우선, 없으면 GridView 값
    let inherit = (colOwn === '');
    let unsupported = (requested === 'onsecondclick');                                                            // onsecondclick 은 editModeEventIcon 미지원

    // 엔진이 셀 td 에 실제 설정한 편집 트리거 이벤트값 (미지원값은 엔진이 onclick 으로 강제)
    let appliedEvt = '';
    try {
        let td = document.querySelector("td[id$='target1_cell_" + rowIndex + "_" + columnIndex + "']");
        if (td) { appliedEvt = td.getAttribute("data-editModeEvent") || td.getAttribute("editModeEvent") || ''; }
    } catch (ex2) { /* td 조회 실패 시 아래 폴백 계산 사용 */ }
    if (appliedEvt === '') { appliedEvt = (requested === 'onclick' || requested === 'ondblclick') ? requested : 'onclick'; }

    let suffix;
    if (unsupported) {
        suffix = " (요청값 onsecondclick 미지원 -> onclick 적용)";
    } else if (inherit) {
        suffix = " (컬럼 editModeEventIcon 미설정 -> GridView editModeEventIcon(" + gridEvt + ") 적용)";
    } else {
        suffix = " (컬럼값 우선)";
    }

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[편집모드 진입] rowIndex=" + rowIndex + ", colIndex=" + columnIndex + ", columnID=" + colId
        + " | 적용 editModeEventIcon = " + appliedEvt + suffix);
}
